module.exports = function (RED) {
    "use strict";

    function PublishNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        // 部署后自动触发一次
        setImmediate(() => {
            node.emit("input", {});
        });

        this.on("input", function (msg, send, done) {

            // 收集当前 flow 下的所有节点（编辑态 JSON）
            const flowNodes = [];
            RED.nodes.eachNode(function (n) {
                if (n.z === node.z) {
                    flowNodes.push(n);
                }
            });

            const postData = JSON.stringify(flowNodes, null, 2);

            console.log("=== POST to backend ===");
            console.log(postData);

            const backendHost = config.backendIp || "127.0.0.1";
            const backendPort = 8080;

            console.log(
                `[Publish] ENV=${config.backendIp || "unknown"}, backend=${backendHost}:${backendPort}`
            );

            // 发起 HTTP POST
            const http = require("http");
            const options = {
                hostname: backendHost,
                port: backendPort,
                path: "/api/node-red/fusion/uploadRule",
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Content-Length": Buffer.byteLength(postData)
                }
            };

            const req = http.request(options, (res) => {
                res.setEncoding("utf8");
                res.on("data", (chunk) => {
                    console.log("Response:", chunk);
                });
                res.on("end", () => {
                    if (done) done();
                });
            });

            req.on("error", (err) => {
                console.error("POST error:", err);
                if (done) done(err);
            });

            req.write(postData);
            req.end();
        });
    }

    RED.nodes.registerType("Publish", PublishNode);
};